-- ============================================================
-- Burnout Detection: Synthetic Dataset
-- 50 Students | 30 Days | 1500 Check-ins
-- Compatible with XAMPP / MySQL 5.7+
-- ============================================================

CREATE DATABASE IF NOT EXISTS burnout_db DEFAULT CHARACTER SET utf8mb4;
USE burnout_db;

DROP TABLE IF EXISTS mood_checkins;
DROP TABLE IF EXISTS students;

CREATE TABLE students (
  student_id   INT PRIMARY KEY,
  name         VARCHAR(60)  NOT NULL,
  age          TINYINT      NOT NULL,
  course       VARCHAR(80)  NOT NULL,
  semester     TINYINT      NOT NULL,
  archetype    VARCHAR(30)  NOT NULL
) ENGINE=InnoDB;

CREATE TABLE mood_checkins (
  checkin_id          INT AUTO_INCREMENT PRIMARY KEY,
  student_id          INT          NOT NULL,
  checkin_date        DATE         NOT NULL,
  day_number          TINYINT      NOT NULL,
  mood_score          DECIMAL(4,2) NOT NULL COMMENT '1.0–10.0',
  sleep_hours         DECIMAL(3,1) NOT NULL,
  study_hours         DECIMAL(4,1) NOT NULL,
  stress_level        DECIMAL(4,2) NOT NULL COMMENT '1.0–10.0',
  social_interactions TINYINT      NOT NULL,
  assignment_load     TINYINT      NOT NULL COMMENT '1=low … 5=very high',
  skipped_class       TINYINT(1)   NOT NULL DEFAULT 0,
  burnout_risk        TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '1=at risk',
  FOREIGN KEY (student_id) REFERENCES students(student_id),
  INDEX idx_student_date (student_id, checkin_date),
  INDEX idx_burnout (burnout_risk)
) ENGINE=InnoDB;



-- ── Useful views for LSTM feature extraction ──────────────────────────────

CREATE OR REPLACE VIEW v_student_sequences AS
SELECT
  m.student_id,
  s.name,
  s.archetype,
  m.checkin_date,
  m.day_number,
  m.mood_score,
  m.sleep_hours,
  m.study_hours,
  m.stress_level,
  m.social_interactions,
  m.assignment_load,
  m.skipped_class,
  m.burnout_risk,
  -- Rolling 3-day mood average
  AVG(m.mood_score) OVER (
      PARTITION BY m.student_id
      ORDER BY m.day_number
      ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS mood_3d_avg,
  -- Rolling 3-day stress average
  AVG(m.stress_level) OVER (
      PARTITION BY m.student_id
      ORDER BY m.day_number
      ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS stress_3d_avg
FROM mood_checkins m
JOIN students s USING (student_id)
ORDER BY m.student_id, m.day_number;

-- Burnout summary per student
CREATE OR REPLACE VIEW v_burnout_summary AS
SELECT
  student_id,
  MAX(s.name)       AS name,
  MAX(s.archetype)  AS archetype,
  COUNT(*)          AS total_days,
  SUM(burnout_risk) AS burnout_days,
  ROUND(AVG(mood_score),2)    AS avg_mood,
  ROUND(AVG(stress_level),2)  AS avg_stress,
  ROUND(AVG(sleep_hours),2)   AS avg_sleep
FROM mood_checkins m
JOIN students s USING (student_id)
GROUP BY student_id
ORDER BY burnout_days DESC;

-- ── Verification queries ─────────────────────────────────────────────
SELECT COUNT(*) AS total_checkins FROM mood_checkins;
SELECT COUNT(DISTINCT student_id) AS total_students FROM mood_checkins;
SELECT archetype, COUNT(DISTINCT student_id) AS n_students, ROUND(AVG(mood_score),2) AS avg_mood FROM mood_checkins m JOIN students s USING(student_id) GROUP BY archetype;
SELECT * FROM v_burnout_summary LIMIT 10;